params.script_inline:
# file-space/derive -- what a file knows about itself (GH #903).
#
# Two jobs, one cell, because both need the same three things -- the text
# view of a version, the embedder and the summarizer -- and this is the ONLY
# cell of the hive that wakes a model or the network (`read`, `write`, `ws`,
# `guard` never do):
#
#   in_derive {file, version}   from `./write` (and `./ws` on a commit) after
#       every head move of the main line: text view -> sections -> one
#       embedding per section -> the one-line and the short summary -> rows in
#       `summaries`/`embeddings`, `files.oneline`. Working versions never get
#       here, and a version that is not on the main line is dropped.
#   in_read op `search` mode `semantic`, op `ask`: the question is embedded,
#       `similar` ranks the sections of THIS file and THIS version only, and
#       `ask` hands the best sections -- never the whole file -- to the
#       summarizer with a fixed brief.
#
# Every store call carries `file` in its `where` (R-FH-1, second condition):
# a hit of file X can never come out of file Y, even when both hold the same
# block. Working values between phases live in `pending` rows of this cell
# (dev-rules 8c), never in the context: the context carries the job id alone
# (`cur_job`, lifted by the edges), because the context is no stack.
#
# `sections(text, kind)` and the other helpers above the program are PURE:
# the locks load them via `ast` without running the per-message program.
import sys, json, re, base64, hashlib, secrets, datetime

ME = "derive"
ONELINE_MAX = 120
SHORT_MAX = 1200
SECTION_LINES = 60
SECTION_OVERLAP = 10
MAX_SECTIONS = 400
EMBED_MAX_CHARS = 8000
SUMMARY_INPUT_MAX = 48000
ASK_SECTIONS = 4
ASK_EXACT_CONTEXT = 2
SEARCH_LIMIT = 20
PREVIEW_LINES = 3
BLOCK_FETCH = 4096
PAGE_FETCH = 1000
PAGE_HEAD = re.compile(r"^--- page (\d+) ---$")
MD_HEAD = re.compile(r"^(#{1,6})\s+(.*?)\s*#*\s*$")
FENCE = re.compile(r"^\s*(```|~~~)")
MD_EXT = (".md", ".markdown", ".mdx")
FMT = "%Y-%m-%dT%H:%M:%S.%fZ"
ID_RE = re.compile(r"^fh-[0-9a-f]{12}$")
HEX_RE = re.compile(r"^[0-9a-f]{4,64}$")
NAME_RE = re.compile(r"^[A-Za-z0-9._-]{1,64}$")
SUMMARY_PROMPT = (
    "Summarize the file below for someone deciding whether to open it. Answer in "
    "exactly this form: the first line is ONE sentence of at most 120 characters "
    "that says what the file is and what it is for; then one empty line; then one "
    "plain paragraph of at most 1200 characters on what it contains. No headings, "
    "no lists, no quotes of the whole file, nothing that is not in the file.")
ASK_PROMPT = (
    "Answer only from these lines; cite line ranges. The lines below are numbered "
    "parts of one file, nothing else is known about it. If they do not hold the "
    "answer, say so in one sentence. End with one line of the form "
    "`SOURCES: <from>-<to>, <from>-<to>` naming the ranges you used.")


# ------------------------------------------------------------------ pure part

# ------------------------------------------------------------ the twins
# `parse_addr`, `line_hash` and `text_view` are word for word the copies in
# `./read` (`script_inline` has no library); the lock
# `gh899_the_twins_parse_one_address` runs every copy against one table, so
# an address, a line hash and a text view mean the same here as in `read`.

def parse_addr(s):
    """An address -> {file, path, at, ref, anchor}; `at` is `head`, `v`
    (`ref` a hex prefix), `ws` or `snap` (`ref` a name). A malformed address
    is {error: 'bad_address'}. An anchor (`#...`) is parsed, never resolved."""
    if not isinstance(s, str) or not s.strip() or len(s) > 1024:
        return {"error": "bad_address"}
    s = s.strip()
    anchor = ""
    if "#" in s:
        s, anchor = s.split("#", 1)
        if not anchor:
            return {"error": "bad_address"}
    at, ref = "head", ""
    if "@" in s:
        base, suffix = s.rsplit("@", 1)
        if suffix.startswith("ws:") or suffix.startswith("snap:"):
            kind, name = suffix.split(":", 1)
            if not NAME_RE.match(name):
                return {"error": "bad_address"}
            at, ref, s = kind, name, base
        elif HEX_RE.match(suffix):
            at, ref, s = "v", suffix, base
        elif ID_RE.match(base):
            return {"error": "bad_address"}
    if ID_RE.match(s):
        return {"file": s, "path": "", "at": at, "ref": ref, "anchor": anchor}
    if s.startswith("/") and "\x00" not in s and "//" not in s and len(s) > 1 \
            and not s.endswith("/"):
        return {"file": "", "path": s, "at": at, "ref": ref, "anchor": anchor}
    return {"error": "bad_address"}


def line_hash(line):
    """`h4`: the first four hex digits of the sha256 of one line without its
    line ending (`\\n`, `\\r\\n`)."""
    if line.endswith("\n"):
        line = line[:-1]
    if line.endswith("\r"):
        line = line[:-1]
    return hashlib.sha256(line.encode("utf-8")).hexdigest()[:4]


def text_view(content, derived):
    """The text a version reads as: its own lines when the content is UTF-8
    without NUL, else its derived pages (`[{part, text}]`), each headed
    `--- page <n> ---`. {kind, lines, pages: {n: [from, to]}} (1-based,
    inclusive) or {error: 'no_text'}. A line keeps a `\\r` of its ending;
    `\\n` ends a line, a last line without one counts."""
    def split(t):
        if t == "":
            return []
        parts = t.split("\n")
        if t.endswith("\n"):
            parts = parts[:-1]
        return parts

    text = None
    if isinstance(content, (bytes, bytearray)) and b"\x00" not in content:
        try:
            text = bytes(content).decode("utf-8")
        except UnicodeDecodeError:
            text = None
    if text is not None:
        return {"kind": "text", "lines": split(text), "pages": {}}
    parts = sorted((p for p in (derived or []) if isinstance(p, dict)),
                   key=lambda p: int(p.get("part") or 0))
    if not parts:
        return {"error": "no_text"}
    lines, pages = [], {}
    for p in parts:
        n = int(p.get("part") or 0)
        start = len(lines) + 1
        lines.append("--- page %d ---" % n)
        lines.extend(split(str(p.get("text") or "")))
        pages[n] = [start, len(lines)]
    return {"kind": "derived", "lines": lines, "pages": pages}


# ------------------------------------------------------------ pure part

def read_form(n, line):
    """One line in the read form `n:h4|text` -- `read`'s `fmt_line`: a
    line's `\\r` is not shown and not hashed, so the `h4` of a hit is the one
    `read` shows and `replace_lines` checks."""
    if line.endswith("\r"):
        line = line[:-1]
    return "%d:%s|%s" % (n, line_hash(line), line)


def split_lines(text):
    """Lines of a text view; a final line end opens no extra empty line."""
    if not text:
        return []
    lines = text.split("\n")
    if text.endswith("\n"):
        lines.pop()
    return lines


def kind_of(path, mime):
    p = str(path or "").lower()
    m = str(mime or "").lower()
    if p.endswith(MD_EXT) or m == "text/markdown":
        return "markdown"
    return "text"


def _units(lines, kind):
    """The hard spans a section never crosses: pages of a text view, headings
    of Markdown, the whole text otherwise. (from_line, to_line, name), 1-based."""
    n = len(lines)
    heads = []
    if kind == "pages":
        heads = [(i + 1, "page " + PAGE_HEAD.match(l).group(1))
                 for i, l in enumerate(lines) if PAGE_HEAD.match(l)]
    elif kind == "markdown":
        fenced = False
        for i, l in enumerate(lines):
            if FENCE.match(l):
                fenced = not fenced
                continue
            m = None if fenced else MD_HEAD.match(l)
            if m and m.group(2):
                heads.append((i + 1, m.group(2)))
    if not heads:
        return [(1, n, "")]
    out = []
    if heads[0][0] > 1:
        out.append((1, heads[0][0] - 1, ""))
    for k, (a, name) in enumerate(heads):
        b = heads[k + 1][0] - 1 if k + 1 < len(heads) else n
        out.append((a, b, name))
    return out


def _windows(a, b, w, o):
    if b - a + 1 <= w:
        return [(a, b)]
    out, start = [], a
    while True:
        end = min(start + w - 1, b)
        out.append((start, end))
        if end == b:
            return out
        start = end - o + 1


def sections(text, kind, window=None, overlap=None, cap=None):
    """Cut a text view into the sections that are embedded one by one.

    Markdown at its headings (not inside fenced code), a text view of pages at
    its `--- page <n> ---` lines, anything else as one span; a span longer than
    `window` lines is cut into windows of `window` lines overlapping by
    `overlap`. Pages and headings are hard borders -- no section crosses one.
    At most `cap` sections: above it the windows grow (double, again and
    again) and, when the borders alone are too many, neighbouring spans are
    joined -- still only at a border. Returns [{section, from_line, to_line,
    text}] in text order; `section` is the heading, the page, or "lines a-b"."""
    window = int(window or SECTION_LINES)
    overlap = int(SECTION_OVERLAP if overlap is None else overlap)
    cap = int(cap or MAX_SECTIONS)
    overlap = max(0, min(overlap, window - 1))
    lines = split_lines(text)
    if not lines:
        return []
    units = _units(lines, kind)
    if len(units) > cap:
        k = -(-len(units) // cap)
        units = [(units[i][0], units[min(i + k, len(units)) - 1][1], units[i][2])
                 for i in range(0, len(units), k)]
    w, o = window, overlap
    while True:
        spans = [(a, b, name) for (ua, ub, name) in units
                 for (a, b) in _windows(ua, ub, w, o)]
        if len(spans) <= cap:
            break
        w, o = w * 2, o * 2
    return [{"section": name or ("lines %d-%d" % (a, b)), "from_line": a,
             "to_line": b, "text": "\n".join(lines[a - 1:b])}
            for (a, b, name) in spans]


def assemble_blocks(hashes, blocks_rows):
    """The bytes of a version from its block list and the `blocks` rows the
    store returned ({hash, enc, body}); None when a block is missing or its
    base64 is broken -- a broken version is never read around. The bytes are
    joined before anything decodes them, so a block cut inside a character
    does not make a text file binary."""
    have = {}
    for r in blocks_rows or []:
        if isinstance(r, dict):
            have[str(r.get("hash") or "")] = r
    parts = []
    for h in hashes:
        r = have.get(str(h))
        if r is None:
            return None
        body = str(r.get("body") or "")
        if str(r.get("enc") or "utf8") == "b64":
            try:
                parts.append(base64.b64decode(body, validate=True))
            except Exception:
                return None
        else:
            parts.append(body.encode("utf-8"))
    return b"".join(parts)


def view_text(content, pages):
    """(text, paged) of a version through the twin `text_view`: `pages` are
    its `derived` rows ({part, body}); the lines come back joined, each ended
    by `\\n`, so `split_lines` gives the twin's lines back one for one (the
    line numbers of a section are `read`'s). (None, False) = no text view."""
    if content is None:
        return None, False
    tv = text_view(content, [{"part": p.get("part"), "text": p.get("body")}
                             for p in pages or [] if isinstance(p, dict)])
    if "error" in tv:
        return None, False
    lines = tv["lines"]
    return ("\n".join(lines) + "\n" if lines else ""), tv["kind"] == "derived"


def block_hashes(raw):
    """`versions.blocks` as a list of hashes (plain strings or {hash})."""
    try:
        v = json.loads(raw) if isinstance(raw, str) else raw
    except Exception:
        return None
    if not isinstance(v, list):
        return None
    out = []
    for x in v:
        h = x.get("hash") if isinstance(x, dict) else x
        if not isinstance(h, str) or not h:
            return None
        out.append(h)
    return out


def basename(path):
    p = str(path or "").rstrip("/")
    return p.rsplit("/", 1)[-1] or p or "file"


def name_oneline(path, mime, kind, size):
    """The one line of a file without a text view -- no model: name and type."""
    what = str(mime or "") or str(kind or "") or "binary"
    return ("%s: %s, %s bytes" % (basename(path), what, int(size or 0)))[:ONELINE_MAX]


def summary_input(path, text, secs):
    head = "Path: %s\n\n" % path
    if len(text) <= SUMMARY_INPUT_MAX:
        return head + text
    cut = text[:SUMMARY_INPUT_MAX]
    rest = [s["section"] for s in secs if s["from_line"] > cut.count("\n") + 1]
    tail = "\n[... cut after %d characters" % SUMMARY_INPUT_MAX
    if rest:
        tail += "; sections of the rest: " + "; ".join(rest[:60])
    return head + cut + tail + "]"


def parse_summary(text):
    """The summarizer's answer as (oneline, short), or None when it is empty.
    First non-empty line = the one line, the rest = the short summary (the
    one line again when the model gave nothing more); both cut to their cap."""
    lines = [l.strip() for l in str(text or "").strip().split("\n")]
    first = next((i for i, l in enumerate(lines) if l), None)
    if first is None:
        return None
    one = lines[first].strip("# ").strip()
    rest = " ".join(l for l in lines[first + 1:] if l).strip()
    one = one[:ONELINE_MAX].rstrip()
    short = (rest or one)[:SHORT_MAX].rstrip()
    return (one, short) if one else None


def exact_hit(question, lines, covered):
    """The one line holding most of the question's words (>= 4 letters,
    case-folded), when no chosen section already covers it: (from, to) with
    ASK_EXACT_CONTEXT lines around it, else None."""
    words = {w for w in re.findall(r"\w+", str(question or "").lower()) if len(w) >= 4}
    if not words:
        return None
    best, best_n = 0, 0
    for i, l in enumerate(lines):
        low = l.lower()
        n = sum(1 for w in words if w in low)
        if n > best_n:
            best, best_n = i + 1, n
    if not best_n or any(a <= best <= b for a, b in covered):
        return None
    return (max(1, best - ASK_EXACT_CONTEXT), min(len(lines), best + ASK_EXACT_CONTEXT))


def ask_input(path, v12, summary, chunks, lines, question):
    out = ["File: %s (version %s)" % (path, v12)]
    if summary:
        out.append("Summary: " + summary)
    for a, b in chunks:
        out.append("")
        out.append("Lines %d-%d:" % (a, b))
        out.extend("%d: %s" % (n, lines[n - 1]) for n in range(a, b + 1))
    out.append("")
    out.append("Question: " + question)
    return "\n".join(out)


def parse_sources(answer, chunks):
    """(answer text, sources) from the model's reply: the `SOURCES:` line names
    the ranges; only ranges that touch a chunk it was given count, and a reply
    that names none cites every chunk it got."""
    named, keep = [], []
    for l in str(answer or "").strip().split("\n"):
        if l.strip().upper().startswith("SOURCES:"):
            for a, b, one in re.findall(r"(\d+)\s*[-\u2013]\s*(\d+)|(\d+)", l.split(":", 1)[1]):
                named.append((int(a or one), int(b or one)))
        else:
            keep.append(l)
    srcs = [(a, b) for a, b in named if a <= b and any(a <= cb and b >= ca for ca, cb in chunks)]
    out = []
    for a, b in srcs or list(chunks):
        if {"from_line": a, "to_line": b} not in out:
            out.append({"from_line": a, "to_line": b})
    return "\n".join(keep).strip(), out


def score(distance, dim):
    bits = max(1, int(dim or 0))
    return round(max(0.0, 1.0 - float(distance or 0) / bits), 4)


# ---------------------------------------------------------------- the program

def now():
    return datetime.datetime.now(datetime.timezone.utc).strftime(FMT)


def emit(msgs):
    sys.stdout.write(json.dumps(msgs))
    sys.exit(0)


def say(msg):
    sys.stderr.write("file-space/derive: %s\n" % msg)


def sel(table, columns, where, order=None, limit=1):
    a = {"operation": "select", "table": table, "columns": columns, "where": where,
         "limit": limit}
    if order:
        a["order_by"] = [{"col": c, "dir": o} for c, o in order]
    return a


def ins(table, row):
    return {"operation": "insert", "table": table, "row": row}


def upd(table, values, where):
    return {"operation": "update", "table": table, "set": values, "where": where}


def dele(table, where):
    return {"operation": "delete", "table": table, "where": where}


def st(ops, phase, job):
    return {"header": {"route": "derive_store", "phase": phase, "reply_cell": ME, "job": job},
            "messages": [{"origin": "assistant", "type": "tool_call", "id": cid,
                          "text": json.dumps(args)} for cid, args in ops]}


def mine(job):
    return {"op_id": job, "cell": ME}


def park_ops(job, state):
    return [("p-upd", upd("pending", {"body": json.dumps(state)}, mine(job))),
            ("p", sel("pending", ["body"], mine(job)))]


def legs(body):
    out = {}
    for m in body.get("messages") or []:
        if not isinstance(m, dict):
            continue
        try:
            payload = json.loads(m.get("text") or "null")
        except Exception:
            payload = None
        out[str(m.get("id") or "")] = {"payload": payload, "error_code": ""}
    results = body.get("results")
    if isinstance(results, list):
        for r in results:
            if isinstance(r, dict):
                leg = out.setdefault(str(r.get("tool_call_id") or ""), {"payload": None})
                leg["error_code"] = str(r.get("error_code") or "")
    elif len(out) == 1:
        next(iter(out.values()))["error_code"] = str(hop.get("error_code") or "")
    return out


def rows(lg, cid):
    p = (lg.get(cid) or {}).get("payload")
    return p if isinstance(p, list) else []


def first(lg, cid):
    r = rows(lg, cid)
    return r[0] if r else None


def errors(lg):
    return ["%s: %s" % (k, v["error_code"]) for k, v in lg.items() if v.get("error_code")]


def parked(lg):
    r = first(lg, "p")
    try:
        return json.loads(str((r or {}).get("body") or ""))
    except Exception:
        return None


def answer(req, fields=None, code=None, message="", job=None, extra=None):
    body = {"ok": code is None, "op": req.get("op", ""), "op_id": req.get("op_id", "")}
    if code is None:
        body.update(fields or {})
    else:
        # A refusal carries its extras inside `error` and no top-level
        # `version` (OR-FH-83, README 2.2 `error: {code, message, current?}`).
        body["error"] = {"code": code, "message": message}
        body["error"].update(extra or {})
    out = [{"header": {"route": "answer", "op": body["op"], "op_id": body["op_id"],
                       "caller": req.get("caller", "")}, **body}]
    if job:
        out.append(st([("p-del", dele("pending", mine(job)))], "noop", job))
    emit(out)


def notify(req, ok, oneline):
    if str(req.get("notify") or "") != "1":
        return []
    v = str(req.get("version") or "")
    return [{"header": {"route": "derived", "caller": req.get("caller", "")},
             "file": req.get("file", ""), "version": v[:12], "ok": bool(ok),
             "oneline": oneline or ""}]


def fail_job(job, req, why):
    """A job that stops: nothing half is written, the rows already there stay,
    and whoever asked with `notify` hears it."""
    say(why)
    emit(notify(req, False, req.get("oneline_was", ""))
         + [st([("p-del", dele("pending", mine(job)))], "noop", job)])


def to_embed(job, texts):
    return {"header": {"route": "embed", "job": job},
            "messages": [{"origin": "assistant", "type": "tool_call", "id": "e-" + job,
                          "text": json.dumps({"texts": texts})}]}


def to_summarizer(job, prompt, text):
    return {"header": {"route": "summarize", "job": job},
            "system": {"instructions": {"text": prompt}},
            "messages": [{"origin": "user", "type": "text", "text": text}]}


def request_of(body):
    """A request body is the JSON object itself; a `messages[]` form with the
    object as its first text is taken too."""
    if isinstance(body.get("op"), str) or isinstance(body.get("file"), str):
        return body
    for m in body.get("messages") or []:
        try:
            v = json.loads(m.get("text") or "")
        except Exception:
            continue
        if isinstance(v, dict):
            return v
    return {}


def knob_str(key, default):
    v = knobs.get(key, default)
    return default if v is None else str(v)


def knob_int(key, default):
    try:
        return int(knobs.get(key, default))
    except (TypeError, ValueError):
        return default


doc = json.load(sys.stdin)
d = doc.get("body") or {}
knobs = doc.get("params") or {}
header = (doc.get("envelope") or {}).get("header") or {}
hop = header.get("hop") or {}
ctx = header.get("context") or {}
lane = str(hop.get("route") or "")
phase = str(ctx.get("cur_phase") or "")
job = str(ctx.get("cur_job") or "")

# ================================================================ lanes

if lane == "in_derive":
    req = request_of(d)
    f, v = str(req.get("file") or ""), str(req.get("version") or "").lower()
    # No drop on `hop.ws` (OR-FH-73): `in_derive` never carries one, and a
    # working version has no `line` row -- `d-text` drops it there, the one
    # rule for "working versions get nothing".
    if not ID_RE.match(f) or not (12 <= len(v) <= 64 and HEX_RE.match(v)):
        say("in_derive without a file id and a version: %r -- dropped" % (req,))
        emit([])
    job = "d-" + secrets.token_hex(8)
    state = {"job": "derive", "file": f, "version": v,
             "notify": str(hop.get("notify") or req.get("notify") or ""),
             "caller": str(hop.get("caller") or "")}
    vwhere = {"file": f, "version": v} if len(v) == 64 else {"file": f, "version": {"gte": v}}
    emit([st([("p-put", ins("pending", {"op_id": job, "cell": ME, "phase": "derive",
                                        "body": json.dumps(state), "at": now()})),
              ("f", sel("files", ["path", "mime", "kind", "bytes", "oneline"], {"file": f})),
              ("v", sel("versions", ["version", "blocks", "bytes"], vwhere,
                        [("version", "asc")], 2)),
              ("born", sel("summaries", ["level"], {"file": f})),
              ("p", sel("pending", ["body"], mine(job)))], "d-load", job)])

if lane == "in_read":
    req = request_of(d)
    op = str(hop.get("op") or req.get("op") or "")
    args = req.get("args") if isinstance(req.get("args"), dict) else {}
    r = {"op": op, "op_id": str(hop.get("op_id") or ""), "caller": str(hop.get("caller") or ""),
         "ws": str(hop.get("ws") or ""), "addr": str(req.get("file") or "")}
    if op == "search":
        r["q"] = str(args.get("pattern") or "")
        try:
            r["limit"] = max(1, min(SEARCH_LIMIT, int(args.get("limit") or SEARCH_LIMIT)))
        except (TypeError, ValueError):
            r["limit"] = SEARCH_LIMIT
    elif op == "ask":
        r["q"] = str(args.get("question") or "")
    else:
        say("in_read op %r is not this cell's -- dropped" % op)
        emit([])
    if not r["op_id"]:
        answer(r, code="bad_request", message="op_id is required")
    if not r["q"].strip():
        answer(r, code="bad_request",
               message="pattern is required" if op == "search" else "question is required")
    # The address as `read` reads it (the twin `parse_addr`, `args.at` joined
    # the same way), so `/a/b.md@<v>` means here what it means there.
    raw, at = r["addr"], args.get("at")
    if at not in (None, "") and "@" not in raw:
        raw = raw + "@" + str(at)
    a = parse_addr(raw)
    if "error" in a:
        answer(r, code=a["error"], message="an address is fh-<12 hex> or /path, with @<hex>, "
               "@ws:<name> or @snap:<name>")
    if a["anchor"]:
        answer(r, code="anchor_unsupported", message="anchors are not served yet")
    r["a"] = a
    job = "r-" + secrets.token_hex(8)
    if a["file"]:
        fsel = sel("files", ["file", "path", "mime", "head", "tomb"], {"file": a["file"]})
    else:
        fsel = sel("files", ["file", "path", "mime", "head", "tomb"], {"path": a["path"], "tomb": ""},
                   [("born_at", "asc")])
    # `hop.ws` and `@ws:<name>` name a workspace by its NAME (OR-FH-81); the
    # open one of that name is the one, as in `read`. Resolved BEFORE the
    # request is parked: parked first, `@ws:<name>` was lost and the op read
    # the head (fix round 2, lock `semantic_ops_resolve_every_address_form_...`).
    wsname = a["ref"] if a["at"] == "ws" else r["ws"]
    if wsname and not NAME_RE.match(wsname):
        answer(r, code="bad_request", message="a workspace name is 1 to 64 of [A-Za-z0-9._-]")
    r["ws"] = wsname
    ops = [("p-put", ins("pending", {"op_id": job, "cell": ME, "phase": "read",
                                     "body": json.dumps(r), "at": now()})),
           ("f", fsel)]
    if wsname:
        ops.append(("w-name", sel("ws", ["ws", "base_seq", "state"], {"name": wsname, "state": "open"},
                                  [("opened_at", "desc")])))
    ops.append(("p", sel("pending", ["body"], mine(job))))
    emit([st(ops, "r-file", job)])

if lane == "embedded":
    m = next((x for x in d.get("messages") or [] if isinstance(x, dict)), {})
    try:
        got = json.loads(m.get("text") or "")
    except Exception:
        got = {}
    got = got if isinstance(got, dict) else {}
    emit([st([("p", sel("pending", ["body"], mine(job))),
              ("x-put", ins("pending", {"op_id": job + ":in", "cell": ME, "phase": "embedded",
                                        "body": json.dumps(got), "at": now()})),
              ("x", sel("pending", ["body"], {"op_id": job + ":in", "cell": ME})),
              ("x-del", dele("pending", {"op_id": job + ":in", "cell": ME}))],
             "embedded", job)])

if lane == "in_summary":
    text = ""
    for m in d.get("messages") or []:
        if isinstance(m, dict) and m.get("origin") == "assistant" and m.get("type") == "text":
            text = str(m.get("text") or "")
            break
    got = {"text": text, "finish": str(hop.get("finish_reason") or ""),
           "model": str(hop.get("model") or ""), "error_code": str(hop.get("error_code") or "")}
    emit([st([("p", sel("pending", ["body"], mine(job))),
              ("x-put", ins("pending", {"op_id": job + ":in", "cell": ME, "phase": "summary",
                                        "body": json.dumps(got), "at": now()})),
              ("x", sel("pending", ["body"], {"op_id": job + ":in", "cell": ME})),
              ("x-del", dele("pending", {"op_id": job + ":in", "cell": ME}))],
             "summary", job)])

if lane:
    say("unknown lane %r -- dropped" % lane)
    emit([])

# ================================================================ phases
if not str(hop.get("operation") or "") or not job:
    say("a message with neither a lane nor a store answer -- dropped")
    emit([])

lg = legs(d)
if phase == "noop":
    for e in errors(lg):
        say("store: " + e)
    emit([])

js = parked(lg)
if js is None:
    say("job %s lost its pending row in phase %s -- dropped" % (job, phase))
    emit([])
bad = errors(lg)
if bad:
    if job.startswith("r-"):
        answer(js, code="store_error", message="; ".join(bad), job=job)
    fail_job(job, js, "store refused in phase %s: %s" % (phase, "; ".join(bad)))


def incoming():
    r = first(lg, "x")
    try:
        return json.loads(str((r or {}).get("body") or ""))
    except Exception:
        return {}


# ------------------------------------------------------------- derive job

def done_seq(mark):
    """The main-line `seq` of the newest version derived for the file, from
    this cell's marker row (`pending` `done:<file>`): the version comparison
    runs over `line`, never over arrival order."""
    try:
        return int(json.loads(str((mark or {}).get("body") or "{}")).get("seq") or 0)
    except Exception:
        return 0


def superseded(state):
    say("%s@%s arrived after a newer version was derived -- it writes nothing"
        % (state["file"], state["version"][:12]))
    emit(notify(state, False, state.get("oneline_was", ""))
         + [st([("p-del", dele("pending", mine(job)))], "noop", job)])


def go(state):
    """Next step of a derive job, in the order of the plan: embeddings, then
    the summary, then the rows."""
    if state.get("want_embed") and state.get("secs") and state.get("vectors") is None:
        texts = [s["text"][:EMBED_MAX_CHARS] or s["section"] for s in state["secs"]]
        emit([to_embed(job, texts)])
    if state.get("want_summary") and state.get("summary") is None:
        emit([to_summarizer(job, SUMMARY_PROMPT, state["summary_input"])])
    f = state["file"]
    emit([st([("mark", sel("pending", ["body"], {"op_id": "done:" + f, "cell": ME})),
              ("p", sel("pending", ["body"], mine(job)))], "d-write", job)])


if phase == "d-load":
    f = first(lg, "f")
    if not f:
        fail_job(job, js, "in_derive for unknown file %s" % js["file"])
    vs = [r for r in rows(lg, "v") if str(r.get("version") or "").startswith(js["version"])]
    if len(vs) != 1:
        fail_job(job, js, "in_derive: %d versions of %s match %s" % (len(vs), js["file"], js["version"]))
    hashes = block_hashes(vs[0].get("blocks"))
    if hashes is None:
        fail_job(job, js, "version %s of %s has no readable block list" % (js["version"], js["file"]))
    js.update({"version": str(vs[0]["version"]), "path": str(f.get("path") or ""),
              "mime": str(f.get("mime") or ""), "fkind": str(f.get("kind") or ""),
              "bytes": vs[0].get("bytes") or f.get("bytes") or 0,
              "oneline_was": str(f.get("oneline") or ""),
              "born": not rows(lg, "born")})
    fw = {"file": js["file"], "version": js["version"]}
    uniq = sorted(set(hashes))
    js["hashes"] = hashes
    emit([st([("l", sel("line", ["seq"], fw, [("seq", "desc")], 1)),
              ("b", sel("blocks", ["hash", "enc", "body"], {"file": js["file"], "hash": {"in": uniq}},
                        None, max(1, len(uniq)))),
              ("g", sel("derived", ["part", "body"], dict(fw, kind="text"), [("part", "asc")],
                        PAGE_FETCH)),
              ("mark", sel("pending", ["body"], {"op_id": "done:" + js["file"], "cell": ME}))]
             + park_ops(job, js), "d-text", job)])

if phase == "d-text":
    line = first(lg, "l")
    if not line:
        fail_job(job, js, "version %s of %s is not on the main line -- nothing derived"
                 % (js["version"][:12], js["file"]))
    js["seq"] = int(line.get("seq") or 0)
    if done_seq(first(lg, "mark")) > js["seq"]:
        # Checked here, before a model or the endpoint is paid, and once more
        # right before the rows are written (`d-write`).
        superseded(js)
    content = assemble_blocks(js.pop("hashes"), rows(lg, "b"))
    if content is None:
        fail_job(job, js, "version %s of %s misses a block -- nothing derived"
                 % (js["version"][:12], js["file"]))
    text, paged = view_text(content, rows(lg, "g"))
    js["want_summary"] = bool(js["born"]) or knob_str("summary_on_commit", "1") == "1"
    js["want_embed"] = knob_str("embed", "1") == "1"
    if text is None or not text.strip():
        # No text view (or an empty file): the one line comes from name and
        # type, without a model, and nothing is embedded.
        js["want_embed"] = False
        js["secs"] = []
        if js["want_summary"]:
            js["summary"] = {"oneline": name_oneline(js["path"], js["mime"], js["fkind"], js["bytes"]),
                            "short": "", "model": ""}
    else:
        kind = "pages" if paged else kind_of(js["path"], js["mime"])
        secs = sections(text, kind, knob_int("section_lines", SECTION_LINES))
        js["secs"] = secs if js["want_embed"] else []
        if js["want_summary"]:
            js["summary_input"] = summary_input(js["path"], text, secs)
    js.setdefault("summary", None)
    js["vectors"] = None
    emit([st(park_ops(job, js), "d-go", job)])

if phase == "d-go":
    go(js)

if phase == "embedded" and job.startswith("d-"):
    got = incoming()
    vec = got.get("vectors")
    if not isinstance(vec, list) or len(vec) != len(js.get("secs") or []) or \
            not all(isinstance(x, str) and x for x in vec):
        fail_job(job, js, "embedding %s@%s failed: %s" % (js["file"], js["version"][:12],
                                                          got.get("error") or "no vectors"))
    js["vectors"] = vec
    js["emodel"] = str(got.get("model") or "")
    js["edim"] = got.get("dim")
    emit([st(park_ops(job, js), "d-go", job)])

if phase == "summary" and job.startswith("d-"):
    got = incoming()
    parsed = parse_summary(got.get("text")) if got.get("finish") == "stop" else None
    if not parsed:
        fail_job(job, js, "summary of %s@%s failed (finish %r, error %r) -- the older summary stays"
                 % (js["file"], js["version"][:12], got.get("finish"), got.get("error_code")))
    js["summary"] = {"oneline": parsed[0], "short": parsed[1], "model": got.get("model", "")}
    js.pop("summary_input", None)
    emit([st(park_ops(job, js), "d-go", job)])

if phase == "d-write":
    f, v = js["file"], js["version"]
    if done_seq(first(lg, "mark")) > js["seq"]:
        superseded(js)
    at = now()
    ops = []
    if js.get("vectors") is not None:
        ops.append(("e-del", dele("embeddings", {"file": f, "version": v})))
        for i, (s, vec) in enumerate(zip(js["secs"], js["vectors"])):
            ops.append(("e-%d" % i, ins("embeddings", {
                "file": f, "version": v, "section": s["section"], "from_line": s["from_line"],
                "to_line": s["to_line"], "blob": vec, "dim": js.get("edim") or 0,
                "model": js.get("emodel") or ""})))
    one = js.get("oneline_was", "")
    if js.get("summary"):
        sm = js["summary"]
        one = sm["oneline"]
        ops.append(("s-one", ins("summaries", {"file": f, "version": v, "level": "oneline",
                                               "text": sm["oneline"], "model": sm["model"], "at": at})))
        if sm["short"]:
            ops.append(("s-short", ins("summaries", {"file": f, "version": v, "level": "short",
                                                     "text": sm["short"], "model": sm["model"],
                                                     "at": at})))
        # Only while `v` is still the head (OR-FH-72): a slow job of an older
        # version never lays its one line over a newer head; zero rows is ok.
        ops.append(("f-one", upd("files", {"oneline": one}, {"file": f, "head": v})))
    js["oneline_now"] = one
    ops += [("m-del", dele("pending", {"op_id": "done:" + f, "cell": ME})),
            ("m-put", ins("pending", {"op_id": "done:" + f, "cell": ME, "phase": v,
                                      "body": json.dumps({"seq": js["seq"]}), "at": at})),
            ("p-upd", upd("pending", {"body": json.dumps(js)}, mine(job))),
            ("p", sel("pending", ["body"], mine(job))),
            ("p-del", dele("pending", mine(job)))]
    emit([st(ops, "d-done", job)])

if phase == "d-done":
    emit(notify(js, True, js.get("oneline_now", "")))

# --------------------------------------------------------------- read job

def v12(v):
    return str(v or "")[:12]


def check_version(js, v):
    """The version is known: look for its embeddings (of the one file), its
    block list and, for `ask`, a summary."""
    js["v"] = v
    fw = {"file": js["f"], "version": v}
    ops = [("e", sel("embeddings", ["model"], fw)),
           ("v", sel("versions", ["blocks"], fw))]
    if js["op"] == "ask":
        ops.append(("s", sel("summaries", ["text", "version"], {"file": js["f"], "level": "short"},
                             [("at", "desc")], 1)))
    emit([st(ops + park_ops(job, js), "r-check", job)])


if phase == "r-file":
    f = first(lg, "f")
    if not f:
        answer(js, code="not_found", message="no file at %r" % js["addr"], job=job)
    js["f"], js["path"] = str(f.get("file") or ""), str(f.get("path") or "")
    a = js["a"]
    # As `read`: a removed file is tombstoned at its head; its versions and
    # snapshots stay addressable.
    if a["at"] == "head" and not js["ws"] and str(f.get("tomb") or ""):
        answer(js, code="tombstoned", message="%s was removed" % js["f"], job=job)
    ws = first(lg, "w-name")
    if js["ws"]:
        if not ws or str(ws.get("state") or "") != "open":
            answer(js, code="ws_unknown", message="no open workspace %r" % (a["ref"] or js["ws"]),
                   job=job)
        js["wsid"] = str(ws.get("ws") or "")
        emit([st([("wf", sel("ws_files", ["working", "state"], {"ws": js["wsid"], "file": js["f"]})),
                  ("wl", sel("line", ["version"], {"file": js["f"], "seq": {"lte": ws.get("base_seq") or 0}},
                             [("seq", "desc")], 1))] + park_ops(job, js), "r-ver", job)])
    if a["at"] == "v":
        emit([st([("vv", sel("versions", ["version"], {"file": js["f"], "version": {"gte": a["ref"]}},
                             [("version", "asc")], 2))] + park_ops(job, js), "r-ver", job)])
    if a["at"] == "snap":
        emit([st([("sn", sel("snaps", ["version"], {"file": js["f"], "name": a["ref"]},
                             [("at", "desc")], 1))] + park_ops(job, js), "r-ver", job)])
    if not str(f.get("head") or ""):
        answer(js, code="not_found", message="%s has no main line yet" % js["f"], job=job)
    check_version(js, str(f["head"]))

if phase == "r-ver":
    a = js["a"]
    if "wsid" in js:
        wf = first(lg, "wf")
        if wf and str(wf.get("state") or "") != "removed":
            # A touched file reads its working version, and working versions
            # are never derived: nothing to rank.
            answer(js, fields=None, code="not_indexed", job=job,
                   message="working versions are not indexed",
                   extra={"current": v12(wf.get("working"))})
        wl = first(lg, "wl")
        if not wl:
            answer(js, code="not_found", message="%s is not in the workspace" % js["f"], job=job)
        check_version(js, str(wl.get("version") or ""))
    if a["at"] == "v":
        vs = [str(r.get("version") or "") for r in rows(lg, "vv")
              if str(r.get("version") or "").startswith(a["ref"])]
        if not vs:
            answer(js, code="version_unknown", message="%s has no version %s" % (js["f"], a["ref"]),
                   job=job)
        if len(vs) > 1:
            answer(js, code="version_ambiguous", message="%s names more than one version" % a["ref"],
                   job=job, extra={"candidates": [v12(x) for x in vs]})
        check_version(js, vs[0])
    sn = first(lg, "sn")
    if not sn:
        answer(js, code="snap_unknown", message="%s has no snapshot %r" % (js["f"], a["ref"]),
               job=job)
    check_version(js, str(sn.get("version") or ""))

if phase == "r-check":
    hashes = block_hashes((first(lg, "v") or {}).get("blocks"))
    if hashes is None:
        answer(js, code="version_unknown", message="%s has no version %s" % (js["f"], v12(js["v"])),
               job=job)
    js["indexed"] = bool(rows(lg, "e"))
    s = first(lg, "s")
    js["summary"] = str((s or {}).get("text") or "")
    js["hashes"] = hashes
    uniq = sorted(set(hashes))
    emit([st([("b", sel("blocks", ["hash", "enc", "body"], {"file": js["f"], "hash": {"in": uniq}},
                        None, max(1, len(uniq)))),
              ("g", sel("derived", ["part", "body"], {"file": js["f"], "version": js["v"], "kind": "text"},
                        [("part", "asc")], PAGE_FETCH))] + park_ops(job, js), "r-text", job)])


def fetch_text(js):
    """The text view of the asked version, or an answer: `corrupt` when a
    block is missing (as `read`), `no_text` without a text view."""
    content = assemble_blocks(js["hashes"], rows(lg, "b"))
    if content is None:
        answer(js, code="corrupt", message="a block of %s@%s is missing" % (js["f"], v12(js["v"])),
               job=job)
    text = view_text(content, rows(lg, "g"))[0]
    if text is None:
        answer(js, code="no_text", message="%s@%s has no text view" % (js["f"], v12(js["v"])), job=job)
    return text


if phase == "r-text":
    fetch_text(js)
    if not js["indexed"]:
        answer(js, code="not_indexed", message="%s@%s has no embeddings" % (js["f"], v12(js["v"])),
               job=job, extra={"current": v12(js["v"])})
    emit([to_embed(job, [js["q"][:EMBED_MAX_CHARS]])])

if phase == "embedded" and job.startswith("r-"):
    got = incoming()
    vec = got.get("vectors")
    if not isinstance(vec, list) or len(vec) != 1 or not isinstance(vec[0], str):
        answer(js, code="embed_failed", message=str(got.get("error") or "no query vector"), job=job)
    js["qv"], js["qmodel"] = vec[0], str(got.get("model") or "")
    k = js["limit"] if js["op"] == "search" else knob_int("ask_sections", ASK_SECTIONS)
    uniq = sorted(set(js["hashes"]))
    emit([st([("sim", {"operation": "similar", "table": "embeddings",
                       "columns": ["section", "from_line", "to_line", "dim"],
                       "vector_column": "blob", "vector": js["qv"],
                       "where": {"file": js["f"], "version": js["v"], "model": js["qmodel"]},
                       "limit": k}),
              ("b", sel("blocks", ["hash", "enc", "body"], {"file": js["f"], "hash": {"in": uniq}},
                        None, max(1, len(uniq)))),
              ("g", sel("derived", ["part", "body"], {"file": js["f"], "version": js["v"], "kind": "text"},
                        [("part", "asc")], PAGE_FETCH)),
              ("p", sel("pending", ["body"], mine(job)))], "r-hits", job)])

if phase == "r-hits":
    lines = split_lines(fetch_text(js))
    hits = rows(lg, "sim")
    if not hits:
        answer(js, code="not_indexed", job=job,
               message="%s@%s has no embeddings of model %r" % (js["f"], v12(js["v"]), js["qmodel"]),
               extra={"current": v12(js["v"])})
    if js["op"] == "search":
        out = []
        for h in hits:
            a, b = int(h.get("from_line") or 1), int(h.get("to_line") or 1)
            out.append({"section": h.get("section", ""), "from_line": a, "to_line": b,
                        "score": score(h.get("distance"), (h.get("dim") or 0)),
                        "preview": [read_form(n, lines[n - 1])
                                    for n in range(a, min(b, a + PREVIEW_LINES - 1) + 1)
                                    if n <= len(lines)]})
        answer(js, {"file": js["f"], "version": v12(js["v"]), "mode": "semantic", "hits": out}, job=job)
    chunks = sorted({(max(1, int(h.get("from_line") or 1)),
                      min(len(lines), int(h.get("to_line") or 1))) for h in hits})
    extra_hit = exact_hit(js["q"], lines, chunks)
    if extra_hit:
        chunks = sorted(chunks + [extra_hit])
    js["chunks"] = chunks
    text = ask_input(js["path"], v12(js["v"]), js["summary"], chunks, lines, js["q"])
    for k in ("hashes", "qv"):
        js.pop(k, None)
    # The park goes out FIRST: the store takes it before the select the
    # summarizer's answer sends, which cannot leave before the model answered.
    emit([st([("p-upd", upd("pending", {"body": json.dumps(js)}, mine(job)))], "noop", job),
          to_summarizer(job, ASK_PROMPT, text)])

if phase == "summary" and job.startswith("r-"):
    got = incoming()
    if got.get("finish") != "stop" or not str(got.get("text") or "").strip():
        answer(js, code="model_failed", job=job,
               message="the summarizer gave no answer (finish %r, error %r)"
               % (got.get("finish"), got.get("error_code")))
    text, srcs = parse_sources(got["text"], [tuple(c) for c in js.get("chunks") or []])
    answer(js, {"file": js["f"], "version": v12(js["v"]), "answer": text, "sources": srcs}, job=job)

say("job %s: phase %r has no step -- dropped" % (job, phase))
emit([])
